export default JSON.parse(
  "{\n  \"workId\": \"han-fei-zi\",\n  \"chapter\": {\n    \"id\": \"han-fei-zi_ch-33\",\n    \"workId\": \"han-fei-zi\",\n    \"order\": 33,\n    \"title\": \"外儲說左下\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 16,\n    \"passageIds\": [\n      \"han-fei-zi_ch-33_p-1\",\n      \"han-fei-zi_ch-33_p-2\",\n      \"han-fei-zi_ch-33_p-3\",\n      \"han-fei-zi_ch-33_p-4\",\n      \"han-fei-zi_ch-33_p-5\",\n      \"han-fei-zi_ch-33_p-6\",\n      \"han-fei-zi_ch-33_p-7\",\n      \"han-fei-zi_ch-33_p-8\",\n      \"han-fei-zi_ch-33_p-9\",\n      \"han-fei-zi_ch-33_p-10\",\n      \"han-fei-zi_ch-33_p-11\",\n      \"han-fei-zi_ch-33_p-12\",\n      \"han-fei-zi_ch-33_p-13\",\n      \"han-fei-zi_ch-33_p-14\",\n      \"han-fei-zi_ch-33_p-15\",\n      \"han-fei-zi_ch-33_p-16\",\n      \"han-fei-zi_ch-33_p-17\",\n      \"han-fei-zi_ch-33_p-18\",\n      \"han-fei-zi_ch-33_p-19\",\n      \"han-fei-zi_ch-33_p-20\",\n      \"han-fei-zi_ch-33_p-21\",\n      \"han-fei-zi_ch-33_p-22\",\n      \"han-fei-zi_ch-33_p-23\",\n      \"han-fei-zi_ch-33_p-24\",\n      \"han-fei-zi_ch-33_p-25\",\n      \"han-fei-zi_ch-33_p-26\",\n      \"han-fei-zi_ch-33_p-27\",\n      \"han-fei-zi_ch-33_p-28\",\n      \"han-fei-zi_ch-33_p-29\",\n      \"han-fei-zi_ch-33_p-30\",\n      \"han-fei-zi_ch-33_p-31\",\n      \"han-fei-zi_ch-33_p-32\",\n      \"han-fei-zi_ch-33_p-33\",\n      \"han-fei-zi_ch-33_p-34\",\n      \"han-fei-zi_ch-33_p-35\",\n      \"han-fei-zi_ch-33_p-36\",\n      \"han-fei-zi_ch-33_p-37\",\n      \"han-fei-zi_ch-33_p-38\",\n      \"han-fei-zi_ch-33_p-39\",\n      \"han-fei-zi_ch-33_p-40\",\n      \"han-fei-zi_ch-33_p-41\",\n      \"han-fei-zi_ch-33_p-42\",\n      \"han-fei-zi_ch-33_p-43\",\n      \"han-fei-zi_ch-33_p-44\",\n      \"han-fei-zi_ch-33_p-45\",\n      \"han-fei-zi_ch-33_p-46\",\n      \"han-fei-zi_ch-33_p-47\",\n      \"han-fei-zi_ch-33_p-48\",\n      \"han-fei-zi_ch-33_p-49\",\n      \"han-fei-zi_ch-33_p-50\",\n      \"han-fei-zi_ch-33_p-51\",\n      \"han-fei-zi_ch-33_p-52\",\n      \"han-fei-zi_ch-33_p-53\",\n      \"han-fei-zi_ch-33_p-54\"\n    ],\n    \"tags\": [\n      \"法家\",\n      \"帝王術\",\n      \"法術勢\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"han-fei-zi_ch-33_p-1\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 1,\n      \"canonicalText\": \"一、以罪受誅，人不怨上，刖危坐子皋。以功受賞，臣不德君，翟璜操右契而乘軒。襄王不知，故昭卯五乘而履屩。上不過任，臣不誣能，即臣將為失少室周。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-1_s-1\",\n        \"han-fei-zi_ch-33_p-1_s-2\",\n        \"han-fei-zi_ch-33_p-1_s-3\",\n        \"han-fei-zi_ch-33_p-1_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一、以罪受誅，人不怨上，刖危坐子皋。以功受賞賜，臣屬不德國君，翟璜操右契而且乘軒。襄王不知，所以昭卯五乘而且履屩。上不過任，臣屬不誣能，即臣屬將為失少室周。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「一、以罪受誅，人不怨上，刖危坐子皋」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「罪」、「受」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一以罪受誅人不怨上刖危坐子皋以功受賞臣不德君翟璜」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「以功受賞，臣不德君，翟璜操右契而乘軒」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-2\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 2,\n      \"canonicalText\": \"二、恃勢而不恃信，故東郭牙議管仲。恃術而不恃信，故渾軒非文公。故有術之主，信賞以盡能，必罰以禁邪，雖有駮行，必得所利，簡主之相陽虎，哀公問一足。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-2_s-1\",\n        \"han-fei-zi_ch-33_p-2_s-2\",\n        \"han-fei-zi_ch-33_p-2_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"二、恃權位威勢而且不恃信，所以東郭牙議管仲。恃督察權術而且不恃信，所以渾軒絕不是文公。所以有督察權術的主，信賞賜以盡能，必刑罰以禁邪，雖有駮行，必得所利，簡主的相陽虎，哀公問一足。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「二、恃勢而不恃信，故東郭牙議管仲」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「二」、「恃」、「勢」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「二恃勢而不恃信故東郭牙議管仲恃術而不恃信故渾軒非」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「恃術而不恃信，故渾軒非文公」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-3\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 3,\n      \"canonicalText\": \"三、失臣主之理，則文王自履而矜。不易朝燕之處，則季孫終身莊而遇賊。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-3_s-1\",\n        \"han-fei-zi_ch-33_p-3_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"三、失臣屬主的理，則文王自履而且矜。不易朝燕的處，則季孫終身莊而且遇賊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「三、失臣主之理，則文王自履而矜」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「三」、「失」、「臣」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「三失臣主之理則文王自履而矜不易朝燕之處則季孫終身」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「不易朝燕之處，則季孫終身莊而遇賊」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-4\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 4,\n      \"canonicalText\": \"四、利所禁，禁所利，雖神不行；譽所罪，毀所賞，雖堯不治。夫為門而不使入，委利而不使進，亂之所以產也。齊侯不聽左右，魏主不聽譽者，而明察照群臣，則鉅不費金錢，孱不用璧，西門豹請復治鄴足以知之。猶盜嬰兒之矜裘，與刖危子榮衣。子綽左右畫，去蟻驅蠅，安得無桓公之憂索官，與宣王之患臞馬也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-4_s-1\",\n        \"han-fei-zi_ch-33_p-4_s-2\",\n        \"han-fei-zi_ch-33_p-4_s-3\",\n        \"han-fei-zi_ch-33_p-4_s-4\",\n        \"han-fei-zi_ch-33_p-4_s-5\",\n        \"han-fei-zi_ch-33_p-4_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"四、利所禁，禁所利，雖神不行；譽所罪，毀所賞賜，雖堯不治。夫為門而且不使入，委利而且不使進，亂的所以產啊。齊侯不聽左右，魏主不聽譽的人或事，而且明察照群臣屬，則鉅不費金錢，孱不用璧，西門豹請復治鄴足以知的。猶盜嬰兒的矜裘，與刖危子榮衣。子綽左右畫，去蟻驅蠅，安得無桓公的憂索官，與宣王的患臞馬啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「四、利所禁，禁所利，雖神不行」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「四」、「利」、「禁」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「四利所禁禁所利雖神不行譽所罪毀所賞雖堯不治夫為門」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「譽所罪，毀所賞，雖堯不治」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-5\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 5,\n      \"canonicalText\": \"五、臣以卑儉為行，則爵不足以觀賞；寵光無節，則臣下侵偪。說在苗賁皇非獻伯，孔子議晏嬰，故仲尼論管仲與叔孫敖。而出入之容變，陽虎之言見其臣也。而簡主之應人臣也失主術。朋黨相和，臣下得欲，則人主孤；群臣公舉，下不相和，則人主明。陽虎將為趙武之賢、解狐之公。而簡主以為枳棘，非所以教國也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-5_s-1\",\n        \"han-fei-zi_ch-33_p-5_s-2\",\n        \"han-fei-zi_ch-33_p-5_s-3\",\n        \"han-fei-zi_ch-33_p-5_s-4\",\n        \"han-fei-zi_ch-33_p-5_s-5\",\n        \"han-fei-zi_ch-33_p-5_s-6\",\n        \"han-fei-zi_ch-33_p-5_s-7\",\n        \"han-fei-zi_ch-33_p-5_s-8\",\n        \"han-fei-zi_ch-33_p-5_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"五、臣屬以卑儉為行，則爵不足以觀賞賜；寵光無節，則臣屬下侵偪。說在苗賁皇絕不是獻伯，孔子議晏嬰，所以仲尼論管仲與叔孫敖。而且出入的容變，陽虎的言見他的臣屬啊。而且簡主的應人臣屬啊失主督察權術。朋黨相和，臣屬下得欲，則人主孤；群臣屬公舉，下不相和，則人主明。陽虎將為趙武的賢、解狐的公。而且簡主以為枳棘，絕不是所以教國啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「五、臣以卑儉為行，則爵不足以觀賞」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「五」、「臣」、「卑」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「五臣以卑儉為行則爵不足以觀賞寵光無節則臣下侵偪說」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「寵光無節，則臣下侵偪」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-6\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 6,\n      \"canonicalText\": \"六、公室卑則忌直言，私行勝則少公功。說在文子之直言，武子之用杖；子產忠諫，子國譙怒；梁車用法，而成侯收璽；管仲以公，而國人謗怨。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-6_s-1\",\n        \"han-fei-zi_ch-33_p-6_s-2\",\n        \"han-fei-zi_ch-33_p-6_s-3\",\n        \"han-fei-zi_ch-33_p-6_s-4\",\n        \"han-fei-zi_ch-33_p-6_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"六、公室卑則忌直言，私行勝則少公功。說在文子的直言，武子的用杖；子產忠諫，子國譙怒；梁車用國家法度法規，而且成侯收璽；管仲以公，而且國人謗怨。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「六、公室卑則忌直言，私行勝則少公功」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「六」、「公」、「室」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「六公室卑則忌直言私行勝則少公功說在文子之直言武子」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「說在文子之直言，武子之用杖」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-7\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 7,\n      \"canonicalText\": \"右經\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-7_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"右經。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「右經」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「右」、「經」、「術」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「右經」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「明法審令」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-8\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 8,\n      \"canonicalText\": \"說一\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-8_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說一。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「說一」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「說」、「一」、「術」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「說一」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「明法審令」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-9\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 9,\n      \"canonicalText\": \"孔子相衛，弟子子皋為獄吏，刖人足，所刖者守門，人有惡孔子於衛君者曰：「尼欲作亂。」衛君欲執孔子，孔子走，弟子皆逃，子皋從出門，刖危引之而逃之門下室中，吏追不得，夜半，子皋問刖危曰：「吾不能虧主之法令而親刖子之足，是子報仇之時也，而子何故乃肯逃我？我何以得此於子？」刖危曰：「吾斷足也，固吾罪當之，不可奈何。然方公之獄治臣也，公傾側法令，先後臣以言，欲臣之免也甚，而臣知之。及獄決罪定，公憱然不悅，形於顏色，臣見又知之。非私臣而然也，夫天性仁心固然也，此臣之所以悅而德公也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-9_s-1\",\n        \"han-fei-zi_ch-33_p-9_s-2\",\n        \"han-fei-zi_ch-33_p-9_s-3\",\n        \"han-fei-zi_ch-33_p-9_s-4\",\n        \"han-fei-zi_ch-33_p-9_s-5\",\n        \"han-fei-zi_ch-33_p-9_s-6\",\n        \"han-fei-zi_ch-33_p-9_s-7\",\n        \"han-fei-zi_ch-33_p-9_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孔子相衛，弟子子皋為獄吏，刖人足，所刖的人或事守門，人有惡孔子於衛國君的人或事說道：尼欲作亂。衛國君欲執孔子，孔子走，弟子皆逃，子皋從出門，刖危引的而且逃的門下室中，吏追不得，夜半，子皋問刖危說道：吾不能虧主的法規法令令而且親刖子的足，是子報仇的時啊，而且子何所以乃肯逃我？我何以得此於子？刖危說道：吾斷足啊，固吾罪當的，不可奈何。然方公的獄治臣屬啊，公傾側法規法令令，先後臣屬以言，欲臣屬的免啊甚，而且臣屬知的。及獄決罪定，公憱然不悅，形於顏色，臣屬見又知的。絕不是私臣屬而且然啊，夫天性仁心固然啊，此臣屬的所以悅而且德公啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「孔子相衛，弟子子皋為獄吏，刖人足，所刖者守門，人有惡孔子於衛君者曰：「尼欲作亂」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「孔」、「子」、「相」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「孔子相衛弟子子皋為獄吏刖人足所刖者守門人有惡孔子」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」衛君欲執孔子，孔子走，弟子皆逃，子皋從出門，刖危引之而逃之門下室中，吏追不得，夜半，子皋問刖危曰：「吾不能虧主之法令而親刖子之足，是子報仇之時也，而子何故乃肯逃我」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-10\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 10,\n      \"canonicalText\": \"田子方從齊之魏，望翟黃乘軒騎駕出，方以為文侯也，移車異路而避之，則徒翟黃也，方問曰：「子奚乘是車也？」曰：「君謀欲伐中山，臣薦翟角而謀得果。且伐之，臣薦樂羊而中山拔。得中山，憂欲治之，臣薦李克而中山治。是以君賜此車。」方曰：「寵之稱功尚薄」。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-10_s-1\",\n        \"han-fei-zi_ch-33_p-10_s-2\",\n        \"han-fei-zi_ch-33_p-10_s-3\",\n        \"han-fei-zi_ch-33_p-10_s-4\",\n        \"han-fei-zi_ch-33_p-10_s-5\",\n        \"han-fei-zi_ch-33_p-10_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"田子方從齊的魏，望翟黃乘軒騎駕出，方以為文侯啊，移車異路而且避的，則徒翟黃啊，方問說道：子奚乘是車啊？說道：國君謀欲伐中山，臣屬薦翟角而且謀得果。且伐的，臣屬薦樂羊而且中山拔。得中山，憂欲治的，臣屬薦李克而且中山治。是以國君賜此車。方說道：寵的稱功尚薄。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「田子方從齊之魏，望翟黃乘軒騎駕出，方以為文侯也，移車異路而避之，則徒翟黃也，方問曰：「子奚乘是車也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「田」、「子」、「方」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「田子方從齊之魏望翟黃乘軒騎駕出方以為文侯也移車異」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」曰：「君謀欲伐中山，臣薦翟角而謀得果」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-11\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 11,\n      \"canonicalText\": \"秦、韓攻魏，昭卯西說而秦、韓罷。齊、荊攻魏，卯東說而齊、荊罷。魏襄王養之以五乘將軍，卯曰：「伯夷以將軍葬於首陽山之下，而天下曰：夫以伯夷之賢與其稱仁，而以將軍葬，是手足不掩也。今臣罷四國之兵，而王乃與臣五乘，此其稱功，猶贏勝而履蹻。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-11_s-1\",\n        \"han-fei-zi_ch-33_p-11_s-2\",\n        \"han-fei-zi_ch-33_p-11_s-3\",\n        \"han-fei-zi_ch-33_p-11_s-4\",\n        \"han-fei-zi_ch-33_p-11_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"秦、韓攻魏，昭卯西說而且秦、韓罷。齊、荊攻魏，卯東說而且齊、荊罷。魏襄王養的以五乘將軍，卯說道：伯夷以將軍葬於首陽山的下，而且天下說道：夫以伯夷的賢與他的稱仁，而且以將軍葬，是手足不掩啊。今臣屬罷四國的兵，而且王乃與臣屬五乘，此他的稱功，猶贏勝而且履蹻。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「秦、韓攻魏，昭卯西說而秦、韓罷」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「秦」、「攻」、「魏」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「秦韓攻魏昭卯西說而秦韓罷齊荊攻魏卯東說而齊荊罷魏」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「齊、荊攻魏，卯東說而齊、荊罷」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-12\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 12,\n      \"canonicalText\": \"孔子曰：「善為吏者樹德，不能為吏者樹怨。概者、平量者也，吏者、平法者也，治國者、不可失平也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-12_s-1\",\n        \"han-fei-zi_ch-33_p-12_s-2\",\n        \"han-fei-zi_ch-33_p-12_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孔子說道：善為吏的人或事樹德，不能為吏的人或事樹怨。概的人或事、平量的人或事啊，吏的人或事、平法規法令的人或事啊，治國的人或事、不可失平啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「孔子曰：「善為吏者樹德，不能為吏者樹怨」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「孔」、「子」、「善」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「孔子曰善為吏者樹德不能為吏者樹怨概者平量者也吏者」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「概者、平量者也，吏者、平法者也，治國者、不可失平也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-13\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 13,\n      \"canonicalText\": \"少室周者，古之貞廉潔愨者也，為趙襄主力士，與中牟徐子角力，不若也，入言之襄主以自代也，襄主曰：「子之處，人之所欲也，何為言徐子以自代？」曰：「臣以力事君者也，今徐子力多臣，臣不以自代，恐他人言之而為罪也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-13_s-1\",\n        \"han-fei-zi_ch-33_p-13_s-2\",\n        \"han-fei-zi_ch-33_p-13_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"少室周的人或事，古的貞廉潔愨的人或事啊，為趙襄主力士，與中牟徐子角力，不若啊，入言的襄主以自代啊，襄主說道：子的處，人的所欲啊，何為言徐子以自代？說道：臣屬以力事國君的人或事啊，今徐子力多臣屬，臣屬不以自代，恐他人言的而且為罪啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「少室周者，古之貞廉潔愨者也，為趙襄主力士，與中牟徐子角力，不若也，入言之襄主以自代也，襄主曰：「子之處，人之所欲也，何為言徐子以自代」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「少」、「室」、「周」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「少室周者古之貞廉潔愨者也為趙襄主力士與中牟徐子角」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」曰：「臣以力事君者也，今徐子力多臣，臣不以自代，恐他人言之而為罪也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-14\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 14,\n      \"canonicalText\": \"一曰。少室周為襄主驂乘，至晉陽，有力士牛子耕與角力而不勝，周言於主曰：「主之所以使臣騎乘者，以臣多力也，今有多力於臣者，願進之。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-14_s-1\",\n        \"han-fei-zi_ch-33_p-14_s-2\",\n        \"han-fei-zi_ch-33_p-14_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。少室周為襄主驂乘，至晉陽，有力士牛子耕與角力而且不勝，周言於主說道：主的所以使臣屬騎乘的人或事，以臣屬多力啊，今有多力於臣屬的人或事，願進的。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「少室周為襄主驂乘，至晉陽，有力士牛子耕與角力而不勝，周言於主曰：「主之所以使臣騎乘者，以臣多力也，今有多力於臣者，願進之」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「少」、「室」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰少室周為襄主驂乘至晉陽有力士牛子耕與角力而不」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「少室周為襄主驂乘，至晉陽，有力士牛子耕與角力而不勝，周言於主曰：「主之所以使臣騎乘者，以臣多力也，今有多力於臣者，願進之」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-15\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 15,\n      \"canonicalText\": \"說二\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-15_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說二。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「說二」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「說」、「二」、「術」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「說二」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「明法審令」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-16\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 16,\n      \"canonicalText\": \"齊桓公將立管仲，令群臣曰：「寡人將立管仲為仲父，善者入門而左，不善者入門而右。」東郭牙中門而立，公曰：「寡人立管仲為仲父，令曰善者左，不善者右，今子何為中門而立？」牙曰：「以管仲之智為能謀天下乎？」公曰：「能」。「以斷為敢行大事乎？」公曰：「敢」。牙曰：「君知能謀天下，斷敢行大事，君因專屬之國柄焉。以管仲之能，乘公之勢以治齊國，得無危乎？」公曰：「善」。乃令隰朋治內，管仲治外以相參。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-16_s-1\",\n        \"han-fei-zi_ch-33_p-16_s-2\",\n        \"han-fei-zi_ch-33_p-16_s-3\",\n        \"han-fei-zi_ch-33_p-16_s-4\",\n        \"han-fei-zi_ch-33_p-16_s-5\",\n        \"han-fei-zi_ch-33_p-16_s-6\",\n        \"han-fei-zi_ch-33_p-16_s-7\",\n        \"han-fei-zi_ch-33_p-16_s-8\",\n        \"han-fei-zi_ch-33_p-16_s-9\",\n        \"han-fei-zi_ch-33_p-16_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"齊桓公將立管仲，令群臣屬說道：寡人將立管仲為仲父，善的人或事入門而且左，不善的人或事入門而且右。東郭牙中門而且立，公說道：寡人立管仲為仲父，令說道：善的人或事左，不善的人或事右，今子何為中門而且立？牙說道：以管仲的智為能謀天下乎？公說道：能。以斷為敢行大事乎？公說道：敢。牙說道：國君知能謀天下，斷敢行大事，國君因專屬的國柄焉。以管仲的能，乘公的權位威勢以治齊國，得無危乎？公說道：善。乃令隰朋治內，管仲治外以相參。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「齊桓公將立管仲，令群臣曰：「寡人將立管仲為仲父，善者入門而左，不善者入門而右」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「齊」、「桓」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「齊桓公將立管仲令群臣曰寡人將立管仲為仲父善者入門」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」東郭牙中門而立，公曰：「寡人立管仲為仲父，令曰善者左，不善者右，今子何為中門而立」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-17\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 17,\n      \"canonicalText\": \"晉文公出亡，箕鄭挈壺餐而從，迷而失道，與公相失，飢而道泣，寢餓而不敢食。及文公反國，舉兵攻原，克而拔之，文公曰：「夫輕忍飢餒之患而必全壺餐，是將不以原叛」。乃舉以為原令。大夫渾軒聞而非之曰：「以不動壺餐之故，怙其不以原叛也，不亦無術乎！故明主者，不恃其不我叛也，恃吾不可叛也；不恃其不我欺也，恃吾不可欺也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-17_s-1\",\n        \"han-fei-zi_ch-33_p-17_s-2\",\n        \"han-fei-zi_ch-33_p-17_s-3\",\n        \"han-fei-zi_ch-33_p-17_s-4\",\n        \"han-fei-zi_ch-33_p-17_s-5\",\n        \"han-fei-zi_ch-33_p-17_s-6\",\n        \"han-fei-zi_ch-33_p-17_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"晉文公出亡，箕鄭挈壺餐而且從，迷而且失道，與公相失，飢而且道泣，寢餓而且不敢食。及文公反國，舉兵攻原，克而且拔的，文公說道：夫輕忍飢餒的患而且必全壺餐，是將不以原叛。乃舉以為原令。大夫渾軒聞而且絕不是的說道：以不動壺餐的所以，怙他的不以原叛啊，不亦無督察權術乎！所以明主的人或事，不恃他的不我叛啊，恃吾不可叛啊；不恃他的不我欺啊，恃吾不可欺啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「晉文公出亡，箕鄭挈壺餐而從，迷而失道，與公相失，飢而道泣，寢餓而不敢食」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「晉」、「文」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「晉文公出亡箕鄭挈壺餐而從迷而失道與公相失飢而道泣」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「及文公反國，舉兵攻原，克而拔之，文公曰：「夫輕忍飢餒之患而必全壺餐，是將不以原叛」」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-18\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 18,\n      \"canonicalText\": \"陽虎議曰：「主賢明則悉心以事之，不肖則飾姦而試之。」逐於魯，疑於齊，走而之趙，趙簡主迎而相之，左右曰：「虎善竊人國政，何故相也？」簡主曰：「陽虎務取之，我務守之。」遂執術而御之，陽虎不敢為非，以善事簡主，興主之強，幾至於霸也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-18_s-1\",\n        \"han-fei-zi_ch-33_p-18_s-2\",\n        \"han-fei-zi_ch-33_p-18_s-3\",\n        \"han-fei-zi_ch-33_p-18_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"陽虎議說道：主賢明則悉心以事的，不肖則飾姦而且試的。逐於魯，疑於齊，走而且的趙，趙簡主迎而且相的，左右說道：虎善竊人國政，何所以相啊？簡主說道：陽虎務取的，我務守的。遂執御臣心術權謀而且御的，陽虎不敢為絕不是，以善事簡主，興主的強，幾至於霸啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「陽虎議曰：「主賢明則悉心以事之，不肖則飾姦而試之」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「陽」、「虎」、「議」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「陽虎議曰主賢明則悉心以事之不肖則飾姦而試之逐於魯」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」逐於魯，疑於齊，走而之趙，趙簡主迎而相之，左右曰：「虎善竊人國政，何故相也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-19\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 19,\n      \"canonicalText\": \"魯哀公問於孔子曰：「吾聞古者有夔一足，其果信有一足乎？孔子對曰：「不也，夔非一足也。夔者忿戾惡心，人多不說喜也。雖然，其所以得免於人害者，以其信也，人皆曰獨此一足矣，夔非一足也，一而足也。」哀公曰：「審而是固足矣。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-19_s-1\",\n        \"han-fei-zi_ch-33_p-19_s-2\",\n        \"han-fei-zi_ch-33_p-19_s-3\",\n        \"han-fei-zi_ch-33_p-19_s-4\",\n        \"han-fei-zi_ch-33_p-19_s-5\",\n        \"han-fei-zi_ch-33_p-19_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"魯哀公問於孔子說道：吾聞古的人或事有夔一足，他的果信有一足乎？孔子對說道：不啊，夔絕不是一足啊。夔的人或事忿戾惡心，人多不說喜啊。雖然，他的所以得免於人害的人或事，以他的信啊，人皆說道：獨此一足矣，夔絕不是一足啊，一而且足啊。哀公說道：審而且是固足矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「魯哀公問於孔子曰：「吾聞古者有夔一足，其果信有一足乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「魯」、「哀」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「魯哀公問於孔子曰吾聞古者有夔一足其果信有一足乎孔」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「孔子對曰：「不也，夔非一足也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-20\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 20,\n      \"canonicalText\": \"一曰。哀公問於孔子曰：「吾聞夔一足，信乎？」曰：「夔，人也，何故一足？彼其無他異，而獨通於聲，堯曰：『夔一而足矣。』使為樂正。故君子曰：『夔有一足，非一足也。』」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-20_s-1\",\n        \"han-fei-zi_ch-33_p-20_s-2\",\n        \"han-fei-zi_ch-33_p-20_s-3\",\n        \"han-fei-zi_ch-33_p-20_s-4\",\n        \"han-fei-zi_ch-33_p-20_s-5\",\n        \"han-fei-zi_ch-33_p-20_s-6\",\n        \"han-fei-zi_ch-33_p-20_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。哀公問於孔子說道：吾聞夔一足，信乎？說道：夔，人啊，何所以一足？彼他的無他異，而且獨通於聲，堯說道：夔一而且足矣。使為樂正。所以君主統治者子說道：夔有一足，絕不是一足啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「哀公問於孔子曰：「吾聞夔一足，信乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「哀」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰哀公問於孔子曰吾聞夔一足信乎曰夔人也何故一足」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」曰：「夔，人也，何故一足」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-21\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 21,\n      \"canonicalText\": \"說三\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-21_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說三。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「說三」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「說」、「三」、「術」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「說三」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「明法審令」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-22\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 22,\n      \"canonicalText\": \"文王伐崇，至鳳黃虛，襪繫解，因自結，太公望曰：「何為也？」王曰：「君與處皆其師，中皆其友，下盡其使也。今皆先君之臣，故無可使也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-22_s-1\",\n        \"han-fei-zi_ch-33_p-22_s-2\",\n        \"han-fei-zi_ch-33_p-22_s-3\",\n        \"han-fei-zi_ch-33_p-22_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"文王伐崇，至鳳黃虛，襪繫解，因自結，太公望說道：何為啊？王說道：國君與處皆他的師，中皆他的友，下盡他的使啊。今皆先國君的臣屬，所以無可使啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「文王伐崇，至鳳黃虛，襪繫解，因自結，太公望曰：「何為也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「文」、「王」、「伐」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「文王伐崇至鳳黃虛襪繫解因自結太公望曰何為也王曰君」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」王曰：「君與處皆其師，中皆其友，下盡其使也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-23\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 23,\n      \"canonicalText\": \"一曰。晉文公與楚戰，至黃鳳之陵，履係解，因自結之，左右曰：「不可以使人乎？」公曰：「吾聞上君所與居，皆其所畏也；中君之所與居，皆其所愛也；下君之所與居，皆其所侮也。寡人雖不肖，先君之人皆在，是以難之也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-23_s-1\",\n        \"han-fei-zi_ch-33_p-23_s-2\",\n        \"han-fei-zi_ch-33_p-23_s-3\",\n        \"han-fei-zi_ch-33_p-23_s-4\",\n        \"han-fei-zi_ch-33_p-23_s-5\",\n        \"han-fei-zi_ch-33_p-23_s-6\",\n        \"han-fei-zi_ch-33_p-23_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。晉文公與楚戰，至黃鳳的陵，履係解，因自結的，左右說道：不可以使人乎？公說道：吾聞上君主統治者所與居，皆他的所畏啊；中君主統治者的所與居，皆他的所愛啊；下君主統治者的所與居，皆他的所侮啊。寡人雖不肖，先君主統治者的人皆在，是以難的啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「晉文公與楚戰，至黃鳳之陵，履係解，因自結之，左右曰：「不可以使人乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「晉」、「文」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰晉文公與楚戰至黃鳳之陵履係解因自結之左右曰不」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」公曰：「吾聞上君所與居，皆其所畏也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-24\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 24,\n      \"canonicalText\": \"季孫好士，終身莊，居處衣服，常如朝廷，而季孫適懈，有過失，而不能長為也，故客以為厭易己，相與怨之，遂殺季孫。故君子去泰去甚。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-24_s-1\",\n        \"han-fei-zi_ch-33_p-24_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"季孫好士，終身莊，居處衣服，常如朝廷，而且季孫適懈，有過失，而且不能長為啊，所以客以為厭易己，相與怨的，遂殺季孫。所以君主統治者子去泰去甚。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「季孫好士，終身莊，居處衣服，常如朝廷，而季孫適懈，有過失，而不能長為也，故客以為厭易己，相與怨之，遂殺季孫」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「季」、「孫」、「好」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「季孫好士終身莊居處衣服常如朝廷而季孫適懈有過失而」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「故君子去泰去甚」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-25\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 25,\n      \"canonicalText\": \"南宮敬子問顏涿聚曰：「季孫養孔子之徒，所朝服與坐者以十數而遇賊，何也？」曰：「昔周成王近優侏儒以逞其意，而與君子斷事，是能成其欲於天下。今季孫養孔子之徒，所朝服而與坐者以十數，而與優侏儒斷事，是以遇賊。故曰：不在所與居，在所與謀也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-25_s-1\",\n        \"han-fei-zi_ch-33_p-25_s-2\",\n        \"han-fei-zi_ch-33_p-25_s-3\",\n        \"han-fei-zi_ch-33_p-25_s-4\",\n        \"han-fei-zi_ch-33_p-25_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"南宮敬子問顏涿聚說道：季孫養孔子的徒，所朝服與坐的人或事以十數而且遇賊，何啊？說道：昔周成王近優侏儒以逞他的意，而且與國君子斷事，是能成他的欲於天下。今季孫養孔子的徒，所朝服而且與坐的人或事以十數，而且與優侏儒斷事，是以遇賊。因此韓絕不是子評論說道：不在所與居，在所與謀啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「南宮敬子問顏涿聚曰：「季孫養孔子之徒，所朝服與坐者以十數而遇賊，何也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「南」、「宮」、「敬」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「南宮敬子問顏涿聚曰季孫養孔子之徒所朝服與坐者以十」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」曰：「昔周成王近優侏儒以逞其意，而與君子斷事，是能成其欲於天下」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-26\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 26,\n      \"canonicalText\": \"孔子御坐於魯哀公，哀公賜之桃與黍，哀公：「請用。」仲尼先飯黍而後啗桃，左右皆揜口而笑，哀公曰：「黍者，非飯之也，以雪桃也。」仲尼對曰：「丘知之矣。夫黍者五穀之長也，祭先王為上盛。果蓏有六，而桃為下，祭先王不得入廟。丘之聞也，君子以賤雪貴，不聞以貴雪賤。今以五穀之長雪果蓏之下，是從上雪下也，丘以為妨義，故不敢以先於宗廟之盛也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-26_s-1\",\n        \"han-fei-zi_ch-33_p-26_s-2\",\n        \"han-fei-zi_ch-33_p-26_s-3\",\n        \"han-fei-zi_ch-33_p-26_s-4\",\n        \"han-fei-zi_ch-33_p-26_s-5\",\n        \"han-fei-zi_ch-33_p-26_s-6\",\n        \"han-fei-zi_ch-33_p-26_s-7\",\n        \"han-fei-zi_ch-33_p-26_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孔子御坐於魯哀公，哀公賜的桃與黍，哀公：請用。仲尼先飯黍而且後啗桃，左右皆揜口而且笑，哀公說道：黍的人或事，絕不是飯的啊，以雪桃啊。仲尼對說道：丘知的矣。夫黍的人或事五穀的長啊，祭先王為上盛。果蓏有六，而且桃為下，祭先王不得入廟。丘的聞啊，國君子以賤雪貴，不聞以貴雪賤。今以五穀的長雪果蓏的下，是從上雪下啊，丘以為妨義，所以不敢以先於宗廟的盛啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「孔子御坐於魯哀公，哀公賜之桃與黍，哀公：「請用」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「孔」、「子」、「御」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「孔子御坐於魯哀公哀公賜之桃與黍哀公請用仲尼先飯黍」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」仲尼先飯黍而後啗桃，左右皆揜口而笑，哀公曰：「黍者，非飯之也，以雪桃也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-27\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 27,\n      \"canonicalText\": \"趙簡子謂左右曰：「車席泰美。夫冠雖賤，頭必戴之；屨雖貴，足必履之。今車席如此，大美，吾將何屩以履之？夫美下而耗上，妨義之本也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-27_s-1\",\n        \"han-fei-zi_ch-33_p-27_s-2\",\n        \"han-fei-zi_ch-33_p-27_s-3\",\n        \"han-fei-zi_ch-33_p-27_s-4\",\n        \"han-fei-zi_ch-33_p-27_s-5\",\n        \"han-fei-zi_ch-33_p-27_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"趙簡子謂左右說道：車席泰美。夫冠雖賤，頭必戴的；屨雖貴，足必履的。今車席如此，大美，吾將何屩以履的？夫美下而且耗上，妨義的本啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「趙簡子謂左右曰：「車席泰美」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「趙」、「簡」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「趙簡子謂左右曰車席泰美夫冠雖賤頭必戴之屨雖貴足必」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「夫冠雖賤，頭必戴之」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-28\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 28,\n      \"canonicalText\": \"費仲說紂曰：「西伯昌賢，百姓悅之，諸侯附焉，不可不誅，不誅必為殷患。」紂曰：「子言，義主，何可誅？」費仲曰：「冠雖穿弊，必戴於頭；履雖五采，必踐之於地。今西伯昌，人臣也，修義而人向之，卒為天下患，其必昌乎！人人不以其賢為其主，非可不誅也。且主而誅臣，焉有過？」紂曰：「夫仁義者，上所以勸下也。今昌好仁義，誅之不可。」三說不用，故亡。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-28_s-1\",\n        \"han-fei-zi_ch-33_p-28_s-2\",\n        \"han-fei-zi_ch-33_p-28_s-3\",\n        \"han-fei-zi_ch-33_p-28_s-4\",\n        \"han-fei-zi_ch-33_p-28_s-5\",\n        \"han-fei-zi_ch-33_p-28_s-6\",\n        \"han-fei-zi_ch-33_p-28_s-7\",\n        \"han-fei-zi_ch-33_p-28_s-8\",\n        \"han-fei-zi_ch-33_p-28_s-9\",\n        \"han-fei-zi_ch-33_p-28_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"費仲說紂說道：西伯昌賢，百姓悅的，諸侯附焉，不可不誅，不誅必為殷患。紂說道：子言，義主，何可誅？費仲說道：冠雖穿弊，必戴於頭；履雖五采，必踐的於地。今西伯昌，人臣屬啊，修義而且人向的，卒為天下患，他的必昌乎！人人不以他的賢為他的主，絕不是可不誅啊。且主而且誅臣屬，焉有過？紂說道：夫仁義的人或事，上所以勸下啊。今昌好仁義，誅的不可。三說不用，所以亡。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「費仲說紂曰：「西伯昌賢，百姓悅之，諸侯附焉，不可不誅，不誅必為殷患」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「費」、「仲」、「說」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「費仲說紂曰西伯昌賢百姓悅之諸侯附焉不可不誅不誅必」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」紂曰：「子言，義主，何可誅」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-29\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 29,\n      \"canonicalText\": \"齊宣王問匡倩曰：「儒者博乎？」曰：「不也。」王曰：「何也？」匡倩對曰：「博者貴梟，勝者必殺梟，殺梟者，是殺所貴也，儒者以為害義，故不博也。」又問曰：「儒者弋乎？」曰：「不也。弋者從下害於上者也，是從下傷君也，儒者以為害義，故不弋。」又問儒者鼓瑟乎？曰：「不也。夫瑟以小絃為大聲，以大絃為小聲，是大小易序，貴賤易位，儒者以為害義，故不鼓也。」宣王曰：「善。」仲尼曰：「與其使民諂下也，寧使民諂上。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-29_s-1\",\n        \"han-fei-zi_ch-33_p-29_s-2\",\n        \"han-fei-zi_ch-33_p-29_s-3\",\n        \"han-fei-zi_ch-33_p-29_s-4\",\n        \"han-fei-zi_ch-33_p-29_s-5\",\n        \"han-fei-zi_ch-33_p-29_s-6\",\n        \"han-fei-zi_ch-33_p-29_s-7\",\n        \"han-fei-zi_ch-33_p-29_s-8\",\n        \"han-fei-zi_ch-33_p-29_s-9\",\n        \"han-fei-zi_ch-33_p-29_s-10\",\n        \"han-fei-zi_ch-33_p-29_s-11\",\n        \"han-fei-zi_ch-33_p-29_s-12\",\n        \"han-fei-zi_ch-33_p-29_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"齊宣王問匡倩說道：儒的人或事博乎？說道：不啊。王說道：何啊？匡倩對說道：博的人或事貴梟，勝的人或事必殺梟，殺梟的人或事，是殺所貴啊，儒的人或事以為害義，所以不博啊。又問說道：儒的人或事弋乎？弋的人或事從下害於上的人或事啊，是從下傷國君啊，儒的人或事以為害義，所以不弋。又問儒的人或事鼓瑟乎？夫瑟以小絃為大聲，以大絃為小聲，是大小易序，貴賤易位，儒的人或事以為害義，所以不鼓啊。宣王說道：善。仲尼說道：與他的使民諂下啊，寧使民諂上。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「齊宣王問匡倩曰：「儒者博乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「齊」、「宣」、「王」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「齊宣王問匡倩曰儒者博乎曰不也王曰何也匡倩對曰博者」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」曰：「不也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-30\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 30,\n      \"canonicalText\": \"說四\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-30_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說四。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「說四」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「說」、「四」、「術」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「說四」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「明法審令」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-31\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 31,\n      \"canonicalText\": \"鉅者，齊之居士。孱者，魏之居士。齊、魏之君不明，不能親照境內，而聽左右之言，故二子費金璧而求入仕也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-31_s-1\",\n        \"han-fei-zi_ch-33_p-31_s-2\",\n        \"han-fei-zi_ch-33_p-31_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"鉅的人或事，齊的居士。孱的人或事，魏的居士。齊、魏的國君不明，不能親照境內，而且聽左右的言，所以二子費金璧而且求入仕啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「鉅者，齊之居士」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「鉅」、「齊」、「居」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「鉅者齊之居士孱者魏之居士齊魏之君不明不能親照境內」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「孱者，魏之居士」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-32\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 32,\n      \"canonicalText\": \"西門豹為鄴令，清剋潔愨，秋毫之端無私利也，而甚簡左右，左右因相與比周而惡之，居期年，上計，君收其璽，豹自請曰：「臣昔者不知所以治鄴，今臣得矣，願請璽復以治鄴，不當，請伏斧鑕之罪。」文侯不忍而復與之，豹因重斂百姓，急事左右，期年，上計，文侯迎而拜之，豹對曰：「往年臣為君治鄴，而君奪臣璽，今臣為左右治鄴，而君拜臣，臣不能治矣。」遂納璽而去，文侯不受，曰：「寡人曩不知子，今知矣，願子勉為寡人治之。」遂不受。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-32_s-1\",\n        \"han-fei-zi_ch-33_p-32_s-2\",\n        \"han-fei-zi_ch-33_p-32_s-3\",\n        \"han-fei-zi_ch-33_p-32_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"西門豹為鄴令，清剋潔愨，秋毫的端無私利啊，而且甚簡左右，左右因相與比周而且惡的，居期年，上計，國君收他的璽，豹自請說道：臣屬昔的人或事不知所以治鄴，今臣屬得矣，願請璽復以治鄴，不當，請伏斧鑕的罪。文侯不忍而且復與的，豹因重斂百姓，急事左右，期年，上計，文侯迎而且拜的，豹對說道：往年臣屬為國君治鄴，而且國君奪臣屬璽，今臣屬為左右治鄴，而且國君拜臣屬，臣屬不能治矣。遂納璽而且去，文侯不受，說道：寡人曩不知子，今知矣，願子勉為寡人治的。遂不受。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「西門豹為鄴令，清剋潔愨，秋毫之端無私利也，而甚簡左右，左右因相與比周而惡之，居期年，上計，君收其璽，豹自請曰：「臣昔者不知所以治鄴，今臣得矣，願請璽復以治鄴，不當，請伏斧鑕之罪」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「西」、「門」、「豹」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「西門豹為鄴令清剋潔愨秋毫之端無私利也而甚簡左右左」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」文侯不忍而復與之，豹因重斂百姓，急事左右，期年，上計，文侯迎而拜之，豹對曰：「往年臣為君治鄴，而君奪臣璽，今臣為左右治鄴，而君拜臣，臣不能治矣」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-33\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 33,\n      \"canonicalText\": \"齊有狗盜之子與刖危子戲而相誇，盜子曰：「吾父之裘獨有尾。」危子曰：「吾父獨冬不失褲。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-33_s-1\",\n        \"han-fei-zi_ch-33_p-33_s-2\",\n        \"han-fei-zi_ch-33_p-33_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"齊有狗盜的子與刖危子戲而且相誇，盜子說道：吾父的裘獨有尾。危子說道：吾父獨冬不失褲。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「齊有狗盜之子與刖危子戲而相誇，盜子曰：「吾父之裘獨有尾」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「齊」、「有」、「狗」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「齊有狗盜之子與刖危子戲而相誇盜子曰吾父之裘獨有尾」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」危子曰：「吾父獨冬不失褲」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-34\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 34,\n      \"canonicalText\": \"子綽曰：「人莫能左畫方而右畫圓也。以肉去蟻蟻愈多，以魚驅蠅蠅愈至。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-34_s-1\",\n        \"han-fei-zi_ch-33_p-34_s-2\",\n        \"han-fei-zi_ch-33_p-34_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"子綽說道：人莫能左畫方而且右畫圓啊。以肉去蟻蟻愈多，以魚驅蠅蠅愈至。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「子綽曰：「人莫能左畫方而右畫圓也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「子」、「綽」、「人」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「子綽曰人莫能左畫方而右畫圓也以肉去蟻蟻愈多以魚驅」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「以肉去蟻蟻愈多，以魚驅蠅蠅愈至」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-35\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 35,\n      \"canonicalText\": \"桓公謂管仲曰：「官少而索者眾，寡人憂之。」管仲曰：「君無聽左右之謂請，因能而受祿，錄功而與官，則莫敢索官，君何患焉？」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-35_s-1\",\n        \"han-fei-zi_ch-33_p-35_s-2\",\n        \"han-fei-zi_ch-33_p-35_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"桓公謂管仲說道：官少而且索的人或事眾，寡人憂的。管仲說道：國君無聽左右的謂請，因能而且受祿，錄功而且與官，則莫敢索官，國君何患焉？\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「桓公謂管仲曰：「官少而索者眾，寡人憂之」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「桓」、「公」、「謂」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「桓公謂管仲曰官少而索者眾寡人憂之管仲曰君無聽左右」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」管仲曰：「君無聽左右之謂請，因能而受祿，錄功而與官，則莫敢索官，君何患焉」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-36\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 36,\n      \"canonicalText\": \"韓宣子曰：「吾馬菽粟多矣，甚臞，何也？寡人患之。」周市對曰：「使騶盡粟以食，雖無肥，不可得也。名為多與之，其實少，雖無臞，亦不可得也。主不審其情實，坐而患之，馬猶不肥也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-36_s-1\",\n        \"han-fei-zi_ch-33_p-36_s-2\",\n        \"han-fei-zi_ch-33_p-36_s-3\",\n        \"han-fei-zi_ch-33_p-36_s-4\",\n        \"han-fei-zi_ch-33_p-36_s-5\",\n        \"han-fei-zi_ch-33_p-36_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"韓宣子說道：吾馬菽粟多矣，甚臞，何啊？寡人患的。周市對說道：使騶盡粟以食，雖無肥，不可得啊。名為多與的，他的實少，雖無臞，亦不可得啊。主不審他的情實，坐而且患的，馬猶不肥啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「韓宣子曰：「吾馬菽粟多矣，甚臞，何也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「宣」、「子」、「吾」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「韓宣子曰吾馬菽粟多矣甚臞何也寡人患之周市對曰使騶」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「寡人患之」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-37\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 37,\n      \"canonicalText\": \"桓公問置吏於管仲，管仲曰：「辯察於辭，清潔於貨，習人情，夷吾不如弦商，請立以為大理。登降肅讓，以明禮待賓，臣不如隰朋，請立以為大行。墾草仞邑，闢地生粟，臣不如甯武，請以為大田。三軍既成陳，使士視死如歸，臣不如公子成父，請以為大司馬。犯顏極諫，臣不如東郭牙，請立以為諫臣。治齊此五子足矣，將欲霸王，夷吾在此。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-37_s-1\",\n        \"han-fei-zi_ch-33_p-37_s-2\",\n        \"han-fei-zi_ch-33_p-37_s-3\",\n        \"han-fei-zi_ch-33_p-37_s-4\",\n        \"han-fei-zi_ch-33_p-37_s-5\",\n        \"han-fei-zi_ch-33_p-37_s-6\",\n        \"han-fei-zi_ch-33_p-37_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"齊桓公向管仲詢問如何安排任命重要官吏，管仲回答說：「在言辭辯析上明察秋毫、對財貨清廉潔白、深悉民情世態，臣不如弦商，請任命他為掌管刑獄法律的大理。升降進退莊重謙讓、以明達禮儀接待各國賓客，臣不如隰朋，請任命他為掌管外交典禮的大行。開墾荒野、築城聚民、闢土墾殖、豐產糧粟，臣不如甯戚，請任命他為掌管農業的大田。三軍陣容齊備之後，能使士卒視死如歸奮勇殺敵，臣不如公子成父，請任命他為掌管軍事的大司馬。敢於冒犯君主威嚴而竭忠極諫，臣不如東郭牙，請立他為專司進諫的諫臣。若僅要治理好齊國，有這五位賢臣便足夠了；如果君主想要成就一統天下的霸王之業，那麼夷吾（管仲）隨時在此聽候差遣。」\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「桓公問置吏於管仲，管仲曰：「辯察於辭，清潔於貨，習人情，夷吾不如弦商，請立以為大理」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「桓」、「公」、「問」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「桓公問置吏於管仲管仲曰辯察於辭清潔於貨習人情夷吾」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「登降肅讓，以明禮待賓，臣不如隰朋，請立以為大行」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-38\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 38,\n      \"canonicalText\": \"說五\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-38_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說五。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「說五」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「說」、「五」、「術」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「說五」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「明法審令」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-39\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 39,\n      \"canonicalText\": \"孟獻伯相魯，堂下生藿藜，門外長荊棘，食不二味，坐不重席，晉無衣帛之妾，居不粟馬，出不從車，叔向聞之，以告苗賁皇，賁皇非之曰：「是出主之爵祿以附下也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-39_s-1\",\n        \"han-fei-zi_ch-33_p-39_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孟獻伯相魯，堂下生藿藜，門外長荊棘，食不二味，坐不重席，晉無衣帛的妾，居不粟馬，出不從車，叔向聞的，以告苗賁皇，賁皇絕不是的說道：是出主的爵祿以附下啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「孟獻伯相魯，堂下生藿藜，門外長荊棘，食不二味，坐不重席，晉無衣帛之妾，居不粟馬，出不從車，叔向聞之，以告苗賁皇，賁皇非之曰：「是出主之爵祿以附下也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「孟」、「獻」、「伯」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「孟獻伯相魯堂下生藿藜門外長荊棘食不二味坐不重席晉」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「孟獻伯相魯，堂下生藿藜，門外長荊棘，食不二味，坐不重席，晉無衣帛之妾，居不粟馬，出不從車，叔向聞之，以告苗賁皇，賁皇非之曰：「是出主之爵祿以附下也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 40,\n      \"canonicalText\": \"一曰。孟獻伯拜上卿，叔嚮往賀，門有御，馬不食禾，向曰：「子無二馬二輿何也？」獻伯曰：「吾觀國人尚有飢色，是以不秣馬。班白者多以徒行，故不二輿。」向曰：「吾始賀子之拜卿，今賀子之儉也。」向出，語苗賁皇曰：「助吾賀獻伯之儉也。」苗子曰：「何賀焉！夫爵祿旂章，所以異功伐別賢不肖也。故晉國之法，上大夫二輿二乘，中大夫二輿一乘，下大夫專乘，此明等級也。且夫卿必有軍事，是故循車馬，比卒乘，以備戎事。有難則以備不虞，平夷則以給朝事。今亂晉國之政，乏不虞之備，以成節，以絜私名，獻伯之儉也可與？又何賀！」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-40_s-1\",\n        \"han-fei-zi_ch-33_p-40_s-2\",\n        \"han-fei-zi_ch-33_p-40_s-3\",\n        \"han-fei-zi_ch-33_p-40_s-4\",\n        \"han-fei-zi_ch-33_p-40_s-5\",\n        \"han-fei-zi_ch-33_p-40_s-6\",\n        \"han-fei-zi_ch-33_p-40_s-7\",\n        \"han-fei-zi_ch-33_p-40_s-8\",\n        \"han-fei-zi_ch-33_p-40_s-9\",\n        \"han-fei-zi_ch-33_p-40_s-10\",\n        \"han-fei-zi_ch-33_p-40_s-11\",\n        \"han-fei-zi_ch-33_p-40_s-12\",\n        \"han-fei-zi_ch-33_p-40_s-13\",\n        \"han-fei-zi_ch-33_p-40_s-14\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。孟獻伯拜上卿，叔嚮往賀，門有御，馬不食禾，向說道：子無二馬二輿何啊？獻伯說道：吾觀國人尚有飢色，是以不秣馬。班白的人或事多以徒行，所以不二輿。向說道：吾始賀子的拜卿，今賀子的儉啊。向出，語苗賁皇說道：助吾賀獻伯的儉啊。苗子說道：何賀焉！夫爵祿旂章，所以異功伐別賢不肖啊。所以晉國的法規法令，上大夫二輿二乘，中大夫二輿一乘，下大夫專乘，此明等級啊。再的人或事況且卿必有軍事，正因為如此循車馬，比卒乘，以備戎事。有難則以備不虞，平夷則以給朝事。今亂晉國的政，乏不虞的備，以成節，以絜私名，獻伯的儉啊可與？又何賀！\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「孟獻伯拜上卿，叔嚮往賀，門有御，馬不食禾，向曰：「子無二馬二輿何也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「孟」、「獻」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰孟獻伯拜上卿叔嚮往賀門有御馬不食禾向曰子無二」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」獻伯曰：「吾觀國人尚有飢色，是以不秣馬」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-41\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 41,\n      \"canonicalText\": \"管仲相齊，曰：「臣貴矣，然而臣貧。」桓公曰：「使子有三歸之家。」曰：「臣富矣，然而臣卑。」桓公使立於高、國之上。曰：「臣尊矣，然而臣疏。」乃立為仲父。孔子聞而非之曰：「泰侈偪上。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-41_s-1\",\n        \"han-fei-zi_ch-33_p-41_s-2\",\n        \"han-fei-zi_ch-33_p-41_s-3\",\n        \"han-fei-zi_ch-33_p-41_s-4\",\n        \"han-fei-zi_ch-33_p-41_s-5\",\n        \"han-fei-zi_ch-33_p-41_s-6\",\n        \"han-fei-zi_ch-33_p-41_s-7\",\n        \"han-fei-zi_ch-33_p-41_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"管仲相齊，說道：臣屬貴矣，然而且臣屬貧。桓公說道：使子有三歸的家。說道：臣屬富矣，然而且臣屬卑。桓公使立於高、國的上。說道：臣屬尊矣，然而且臣屬疏。乃立為仲父。孔子聞而且絕不是的說道：泰侈偪上。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「管仲相齊，曰：「臣貴矣，然而臣貧」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「管」、「仲」、「相」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「管仲相齊曰臣貴矣然而臣貧桓公曰使子有三歸之家曰臣」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」桓公曰：「使子有三歸之家」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-42\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 42,\n      \"canonicalText\": \"一曰。管仲父，出、朱蓋青衣，置鼓而歸，庭有陳鼎，家有三歸，孔子曰：「良大夫也，其侈偪上。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-42_s-1\",\n        \"han-fei-zi_ch-33_p-42_s-2\",\n        \"han-fei-zi_ch-33_p-42_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。管仲父，出、朱蓋青衣，置鼓而且歸，庭有陳鼎，家有三歸，孔子說道：良大夫啊，他的侈偪上。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「管仲父，出、朱蓋青衣，置鼓而歸，庭有陳鼎，家有三歸，孔子曰：「良大夫也，其侈偪上」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「管」、「仲」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰管仲父出朱蓋青衣置鼓而歸庭有陳鼎家有三歸孔子」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「管仲父，出、朱蓋青衣，置鼓而歸，庭有陳鼎，家有三歸，孔子曰：「良大夫也，其侈偪上」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-43\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 43,\n      \"canonicalText\": \"孫叔敖相楚，棧車牝馬，糲餅菜羹，枯魚之膳，冬羔裘，夏葛衣，面有飢色，則良大夫也，其儉偪下。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-43_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孫叔敖相楚，棧車牝馬，糲餅菜羹，枯魚的膳，冬羔裘，夏葛衣，面有飢色，則良大夫啊，他的儉偪下。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「孫叔敖相楚，棧車牝馬，糲餅菜羹，枯魚之膳，冬羔裘，夏葛衣，面有飢色，則良大夫也，其儉偪下」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「孫」、「叔」、「敖」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「孫叔敖相楚棧車牝馬糲餅菜羹枯魚之膳冬羔裘夏葛衣面」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「孫叔敖相楚，棧車牝馬，糲餅菜羹，枯魚之膳，冬羔裘，夏葛衣，面有飢色，則良大夫也，其儉偪下」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-44\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 44,\n      \"canonicalText\": \"陽虎去齊走趙，簡主問曰：「吾聞子善樹人。」虎曰：「臣居魯，樹三人，皆為令尹，及虎抵罪於魯，皆搜索於虎也。臣居齊，薦三人，一人得近王，一人為縣令，一人為候吏，及臣得罪，近王者不見臣，縣令者迎臣執縛，候吏者追臣至境上，不及而止。虎不善樹人。」主俛而笑曰：「夫樹橘柚者，食之則甘，嗅之則香；樹枳棘者，成而刺人；故君子慎所樹。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-44_s-1\",\n        \"han-fei-zi_ch-33_p-44_s-2\",\n        \"han-fei-zi_ch-33_p-44_s-3\",\n        \"han-fei-zi_ch-33_p-44_s-4\",\n        \"han-fei-zi_ch-33_p-44_s-5\",\n        \"han-fei-zi_ch-33_p-44_s-6\",\n        \"han-fei-zi_ch-33_p-44_s-7\",\n        \"han-fei-zi_ch-33_p-44_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"陽虎去齊走趙，簡主問說道：吾聞子善樹人。虎說道：臣屬居魯，樹三人，皆為令尹，及虎抵罪於魯，皆搜索於虎啊。臣屬居齊，薦三人，一人得近王，一人為縣令，一人為候吏，及臣屬得罪，近王的人或事不見臣屬，縣令的人或事迎臣屬執縛，候吏的人或事追臣屬至境上，不及而且止。虎不善樹人。主俛而且笑說道：夫樹橘柚的人或事，食的則甘，嗅的則香；樹枳棘的人或事，成而且刺人；所以國君子慎所樹。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「陽虎去齊走趙，簡主問曰：「吾聞子善樹人」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「陽」、「虎」、「去」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「陽虎去齊走趙簡主問曰吾聞子善樹人虎曰臣居魯樹三人」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」虎曰：「臣居魯，樹三人，皆為令尹，及虎抵罪於魯，皆搜索於虎也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-45\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 45,\n      \"canonicalText\": \"中牟無令，晉平公問趙武曰：「中牟，三國之股肱，邯鄲之肩髀，寡人慾得其良令也，誰使而可？」武曰：「邢伯子可。」公曰：「非子之讎也？」曰：「私讎不入公門。」公又問曰：「中府之令誰使而可？」曰：「臣子可。」故曰：「外舉不避讎，內舉不避子。」趙武所薦四十六人，及武死，各就賓位，其無私德若此也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-45_s-1\",\n        \"han-fei-zi_ch-33_p-45_s-2\",\n        \"han-fei-zi_ch-33_p-45_s-3\",\n        \"han-fei-zi_ch-33_p-45_s-4\",\n        \"han-fei-zi_ch-33_p-45_s-5\",\n        \"han-fei-zi_ch-33_p-45_s-6\",\n        \"han-fei-zi_ch-33_p-45_s-7\",\n        \"han-fei-zi_ch-33_p-45_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"中牟無令，晉平公問趙武說道：中牟，三國的股肱，邯鄲的肩髀，寡人慾得他的良令啊，誰使而且可？武說道：邢伯子可。公說道：絕不是子的讎啊？說道：私讎不入公門。公又問說道：中府的令誰使而且可？說道：臣屬子可。因此韓絕不是子評論說道：外舉不避讎，內舉不避子。趙武所薦四十六人，及武死，各就賓位，他的無私德若此啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「中牟無令，晉平公問趙武曰：「中牟，三國之股肱，邯鄲之肩髀，寡人慾得其良令也，誰使而可」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「中」、「牟」、「無」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「中牟無令晉平公問趙武曰中牟三國之股肱邯鄲之肩髀寡」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」武曰：「邢伯子可」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-46\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 46,\n      \"canonicalText\": \"平公問叔向曰：「群臣孰賢？」曰：「趙武。」公曰：「子黨於師人。」曰：「武立如不勝衣，言如不出口，然所舉士也數十人，皆得其意，而公家甚賴之，及武子之生也不利於家，死不託於孤，臣敢以為賢也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-46_s-1\",\n        \"han-fei-zi_ch-33_p-46_s-2\",\n        \"han-fei-zi_ch-33_p-46_s-3\",\n        \"han-fei-zi_ch-33_p-46_s-4\",\n        \"han-fei-zi_ch-33_p-46_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"平公問叔向說道：群臣屬孰賢？說道：趙武。公說道：子黨於師人。說道：武立如不勝衣，言如不出口，然所舉士啊數十人，皆得他的意，而且公家甚賴的，及武子的生啊不利於家，死不託於孤，臣屬敢以為賢啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「平公問叔向曰：「群臣孰賢」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「平」、「公」、「問」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「平公問叔向曰群臣孰賢曰趙武公曰子黨於師人曰武立如」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」曰：「趙武」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-47\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 47,\n      \"canonicalText\": \"解狐薦其讎於簡主以為相，其讎以為且幸釋己也，乃因往拜謝，狐乃引弓送而射之，曰：「夫薦汝公也，以汝能當之也。夫讎汝，吾私怨也，不以私怨汝之故擁汝於吾君。故私怨不入公門。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-47_s-1\",\n        \"han-fei-zi_ch-33_p-47_s-2\",\n        \"han-fei-zi_ch-33_p-47_s-3\",\n        \"han-fei-zi_ch-33_p-47_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"解狐薦他的讎於簡主以為相，他的讎以為且幸釋己啊，乃因往拜謝，狐乃引弓送而且射的，說道：夫薦汝公啊，以汝能當的啊。夫讎汝，吾私怨啊，不以私怨汝的所以擁汝於吾君主統治者。所以私怨不入公門。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「解狐薦其讎於簡主以為相，其讎以為且幸釋己也，乃因往拜謝，狐乃引弓送而射之，曰：「夫薦汝公也，以汝能當之也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「解」、「狐」、「薦」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「解狐薦其讎於簡主以為相其讎以為且幸釋己也乃因往拜」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「夫讎汝，吾私怨也，不以私怨汝之故擁汝於吾君」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-48\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 48,\n      \"canonicalText\": \"一曰。解狐舉邢伯柳為上黨守，柳往謝之曰：「子釋罪，敢不再拜。」曰：「舉子公也，怨子私也，子往矣，怨子如初也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-48_s-1\",\n        \"han-fei-zi_ch-33_p-48_s-2\",\n        \"han-fei-zi_ch-33_p-48_s-3\",\n        \"han-fei-zi_ch-33_p-48_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"一說道：。解狐舉邢伯柳為上黨守，柳往謝的說道：子釋罪，敢不再拜。說道：舉子公啊，怨子私啊，子往矣，怨子如初啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「解狐舉邢伯柳為上黨守，柳往謝之曰：「子釋罪，敢不再拜」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「一」、「解」、「狐」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「一曰解狐舉邢伯柳為上黨守柳往謝之曰子釋罪敢不再拜」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」曰：「舉子公也，怨子私也，子往矣，怨子如初也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-49\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 49,\n      \"canonicalText\": \"鄭縣人賣豚，人問其價，曰：「道日暮安暇語汝。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-49_s-1\",\n        \"han-fei-zi_ch-33_p-49_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"鄭縣人賣豚，人問他的價，說道：道日暮安暇語汝。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「鄭縣人賣豚，人問其價，曰：「道日暮安暇語汝」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「鄭」、「縣」、「人」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「鄭縣人賣豚人問其價曰道日暮安暇語汝」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「鄭縣人賣豚，人問其價，曰：「道日暮安暇語汝」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-50\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 50,\n      \"canonicalText\": \"說六\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-50_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說六。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「說六」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「說」、「六」、「術」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「說六」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「明法審令」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-51\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 51,\n      \"canonicalText\": \"範文子喜直言，武子擊之以杖：「夫直議者不為人所容，無所容則危身，非徒危身，又將危父。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-51_s-1\",\n        \"han-fei-zi_ch-33_p-51_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"晉國大夫范文子平日喜歡直言進諫，他的父親范武子憤怒地拿手杖擊打他並斥責道：「直言規勸批評的人，向來不為當世之人所容納；在世上無容身之地就會招致殺身之禍，這不僅是危害你自己，將來還會給父親與宗族招來滅頂之災！」\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「範文子喜直言，武子擊之以杖：「夫直議者不為人所容，無所容則危身，非徒危身，又將危父」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「範」、「文」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「範文子喜直言武子擊之以杖夫直議者不為人所容無所容」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「範文子喜直言，武子擊之以杖：「夫直議者不為人所容，無所容則危身，非徒危身，又將危父」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-52\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 52,\n      \"canonicalText\": \"子產者，子國之子也。子產忠於鄭君，子國譙怒之曰：「夫介異於人臣，而獨忠於主，主賢明，能聽汝，不明，將不汝聽，聽與不聽，未可必知，而汝已離於群臣，離於群臣則必危汝身矣，非徒危己也，又且危父矣。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-52_s-1\",\n        \"han-fei-zi_ch-33_p-52_s-2\",\n        \"han-fei-zi_ch-33_p-52_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"子產的人或事，子國的子啊。子產忠於鄭國君，子國譙怒的說道：夫介異於人臣屬，而且獨忠於主，主賢明，能聽汝，不明，將不汝聽，聽與不聽，未可必知，而且汝已離於群臣屬，離於群臣屬則必危汝身矣，絕不是徒危己啊，又且危父矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「子產者，子國之子也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「子」、「產」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「子產者子國之子也子產忠於鄭君子國譙怒之曰夫介異於」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「子產忠於鄭君，子國譙怒之曰：「夫介異於人臣，而獨忠於主，主賢明，能聽汝，不明，將不汝聽，聽與不聽，未可必知，而汝已離於群臣，離於群臣則必危汝身矣，非徒危己也，又且危父矣」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-53\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 53,\n      \"canonicalText\": \"梁車新為鄴令，其姊往看之，暮而後門閉，因踰郭而入，車遂刖其足，趙成侯以為不慈，奪之璽而免之令。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-53_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"梁車新為鄴令，他的姊往看的，暮而且後門閉，因踰郭而且入，車遂刖他的足，趙成侯以為不慈，奪的璽而且免的令。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「梁車新為鄴令，其姊往看之，暮而後門閉，因踰郭而入，車遂刖其足，趙成侯以為不慈，奪之璽而免之令」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「梁」、「車」、「新」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「梁車新為鄴令其姊往看之暮而後門閉因踰郭而入車遂刖」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「梁車新為鄴令，其姊往看之，暮而後門閉，因踰郭而入，車遂刖其足，趙成侯以為不慈，奪之璽而免之令」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-54\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"order\": 54,\n      \"canonicalText\": \"管仲束縛，自魯之齊，道而飢渴，過綺烏封人而乞食，烏封人跪而食之，甚敬，封人因竊謂仲曰：「適幸及齊不死而用齊，將何報我？」曰：「如子之言，我且賢之用，能之使，勞之論，我何以報子？」封人怨之。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-33_p-54_s-1\",\n        \"han-fei-zi_ch-33_p-54_s-2\",\n        \"han-fei-zi_ch-33_p-54_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"管仲束縛，自魯的齊，道而且飢渴，過綺烏封人而且乞食，烏封人跪而且食的，甚敬，封人因竊謂仲說道：適幸及齊不死而且用齊，將何報我？說道：如子的言，我且賢的用，能的使，勞的論，我何以報子？封人怨的。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈外儲說左下〉。韓非深刻融合法、術、勢三大治國精要，此處「管仲束縛，自魯之齊，道而飢渴，過綺烏封人而乞食，烏封人跪而食之，甚敬，封人因竊謂仲曰：「適幸及齊不死而用齊，將何報我」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「管」、「仲」、「束」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「管仲束縛自魯之齊道而飢渴過綺烏封人而乞食烏封人跪」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」曰：「如子之言，我且賢之用，能之使，勞之論，我何以報子」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"han-fei-zi_ch-33_p-1_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"一、以罪受誅，人不怨上，刖危坐子皋。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-1_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"以功受賞，臣不德君，翟璜操右契而乘軒。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-1_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"襄王不知，故昭卯五乘而履屩。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-1_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"上不過任，臣不誣能，即臣將為失少室周。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-2_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"二、恃勢而不恃信，故東郭牙議管仲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-2_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"恃術而不恃信，故渾軒非文公。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-2_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"故有術之主，信賞以盡能，必罰以禁邪，雖有駮行，必得所利，簡主之相陽虎，哀公問一足。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-3_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"三、失臣主之理，則文王自履而矜。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-3_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"不易朝燕之處，則季孫終身莊而遇賊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-4_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"四、利所禁，禁所利，雖神不行；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-4_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"譽所罪，毀所賞，雖堯不治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-4_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"夫為門而不使入，委利而不使進，亂之所以產也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-4_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"齊侯不聽左右，魏主不聽譽者，而明察照群臣，則鉅不費金錢，孱不用璧，西門豹請復治鄴足以知之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-4_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"猶盜嬰兒之矜裘，與刖危子榮衣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-4_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"子綽左右畫，去蟻驅蠅，安得無桓公之憂索官，與宣王之患臞馬也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-5_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"五、臣以卑儉為行，則爵不足以觀賞；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-5_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"寵光無節，則臣下侵偪。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-5_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"說在苗賁皇非獻伯，孔子議晏嬰，故仲尼論管仲與叔孫敖。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-5_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"而出入之容變，陽虎之言見其臣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-5_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"而簡主之應人臣也失主術。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-5_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"朋黨相和，臣下得欲，則人主孤；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-5_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"群臣公舉，下不相和，則人主明。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-5_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-5\",\n      \"order\": 8,\n      \"canonicalText\": \"陽虎將為趙武之賢、解狐之公。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-5_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-5\",\n      \"order\": 9,\n      \"canonicalText\": \"而簡主以為枳棘，非所以教國也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-6_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"六、公室卑則忌直言，私行勝則少公功。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-6_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"說在文子之直言，武子之用杖；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-6_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"子產忠諫，子國譙怒；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-6_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"梁車用法，而成侯收璽；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-6_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"管仲以公，而國人謗怨。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-7_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"右經\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-8_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"說一\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-9_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"孔子相衛，弟子子皋為獄吏，刖人足，所刖者守門，人有惡孔子於衛君者曰：「尼欲作亂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-9_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"」衛君欲執孔子，孔子走，弟子皆逃，子皋從出門，刖危引之而逃之門下室中，吏追不得，夜半，子皋問刖危曰：「吾不能虧主之法令而親刖子之足，是子報仇之時也，而子何故乃肯逃我？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-9_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"我何以得此於子？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-9_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"」刖危曰：「吾斷足也，固吾罪當之，不可奈何。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-9_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-9\",\n      \"order\": 5,\n      \"canonicalText\": \"然方公之獄治臣也，公傾側法令，先後臣以言，欲臣之免也甚，而臣知之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-9_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-9\",\n      \"order\": 6,\n      \"canonicalText\": \"及獄決罪定，公憱然不悅，形於顏色，臣見又知之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-9_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-9\",\n      \"order\": 7,\n      \"canonicalText\": \"非私臣而然也，夫天性仁心固然也，此臣之所以悅而德公也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-9_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-9\",\n      \"order\": 8,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-10_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"田子方從齊之魏，望翟黃乘軒騎駕出，方以為文侯也，移車異路而避之，則徒翟黃也，方問曰：「子奚乘是車也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-10_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"」曰：「君謀欲伐中山，臣薦翟角而謀得果。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-10_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"且伐之，臣薦樂羊而中山拔。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-10_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"得中山，憂欲治之，臣薦李克而中山治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-10_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"是以君賜此車。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-10_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"」方曰：「寵之稱功尚薄」。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-11_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"秦、韓攻魏，昭卯西說而秦、韓罷。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-11_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"齊、荊攻魏，卯東說而齊、荊罷。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-11_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"魏襄王養之以五乘將軍，卯曰：「伯夷以將軍葬於首陽山之下，而天下曰：夫以伯夷之賢與其稱仁，而以將軍葬，是手足不掩也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-11_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"今臣罷四國之兵，而王乃與臣五乘，此其稱功，猶贏勝而履蹻。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-11_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-11\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-12_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"孔子曰：「善為吏者樹德，不能為吏者樹怨。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-12_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"概者、平量者也，吏者、平法者也，治國者、不可失平也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-12_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-13_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"少室周者，古之貞廉潔愨者也，為趙襄主力士，與中牟徐子角力，不若也，入言之襄主以自代也，襄主曰：「子之處，人之所欲也，何為言徐子以自代？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-13_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"」曰：「臣以力事君者也，今徐子力多臣，臣不以自代，恐他人言之而為罪也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-13_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-13\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-14_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-14_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-14\",\n      \"order\": 2,\n      \"canonicalText\": \"少室周為襄主驂乘，至晉陽，有力士牛子耕與角力而不勝，周言於主曰：「主之所以使臣騎乘者，以臣多力也，今有多力於臣者，願進之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-14_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-14\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-15_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-15\",\n      \"order\": 1,\n      \"canonicalText\": \"說二\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-16_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-16\",\n      \"order\": 1,\n      \"canonicalText\": \"齊桓公將立管仲，令群臣曰：「寡人將立管仲為仲父，善者入門而左，不善者入門而右。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-16_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-16\",\n      \"order\": 2,\n      \"canonicalText\": \"」東郭牙中門而立，公曰：「寡人立管仲為仲父，令曰善者左，不善者右，今子何為中門而立？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-16_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-16\",\n      \"order\": 3,\n      \"canonicalText\": \"」牙曰：「以管仲之智為能謀天下乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-16_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-16\",\n      \"order\": 4,\n      \"canonicalText\": \"」公曰：「能」。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-16_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-16\",\n      \"order\": 5,\n      \"canonicalText\": \"「以斷為敢行大事乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-16_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-16\",\n      \"order\": 6,\n      \"canonicalText\": \"」公曰：「敢」。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-16_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-16\",\n      \"order\": 7,\n      \"canonicalText\": \"牙曰：「君知能謀天下，斷敢行大事，君因專屬之國柄焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-16_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-16\",\n      \"order\": 8,\n      \"canonicalText\": \"以管仲之能，乘公之勢以治齊國，得無危乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-16_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-16\",\n      \"order\": 9,\n      \"canonicalText\": \"」公曰：「善」。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-16_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-16\",\n      \"order\": 10,\n      \"canonicalText\": \"乃令隰朋治內，管仲治外以相參。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-17_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-17\",\n      \"order\": 1,\n      \"canonicalText\": \"晉文公出亡，箕鄭挈壺餐而從，迷而失道，與公相失，飢而道泣，寢餓而不敢食。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-17_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-17\",\n      \"order\": 2,\n      \"canonicalText\": \"及文公反國，舉兵攻原，克而拔之，文公曰：「夫輕忍飢餒之患而必全壺餐，是將不以原叛」。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-17_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-17\",\n      \"order\": 3,\n      \"canonicalText\": \"乃舉以為原令。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-17_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-17\",\n      \"order\": 4,\n      \"canonicalText\": \"大夫渾軒聞而非之曰：「以不動壺餐之故，怙其不以原叛也，不亦無術乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-17_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-17\",\n      \"order\": 5,\n      \"canonicalText\": \"故明主者，不恃其不我叛也，恃吾不可叛也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-17_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-17\",\n      \"order\": 6,\n      \"canonicalText\": \"不恃其不我欺也，恃吾不可欺也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-17_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-17\",\n      \"order\": 7,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-18_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-18\",\n      \"order\": 1,\n      \"canonicalText\": \"陽虎議曰：「主賢明則悉心以事之，不肖則飾姦而試之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-18_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-18\",\n      \"order\": 2,\n      \"canonicalText\": \"」逐於魯，疑於齊，走而之趙，趙簡主迎而相之，左右曰：「虎善竊人國政，何故相也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-18_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-18\",\n      \"order\": 3,\n      \"canonicalText\": \"」簡主曰：「陽虎務取之，我務守之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-18_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-18\",\n      \"order\": 4,\n      \"canonicalText\": \"」遂執術而御之，陽虎不敢為非，以善事簡主，興主之強，幾至於霸也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-19_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-19\",\n      \"order\": 1,\n      \"canonicalText\": \"魯哀公問於孔子曰：「吾聞古者有夔一足，其果信有一足乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-19_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-19\",\n      \"order\": 2,\n      \"canonicalText\": \"孔子對曰：「不也，夔非一足也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-19_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-19\",\n      \"order\": 3,\n      \"canonicalText\": \"夔者忿戾惡心，人多不說喜也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-19_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-19\",\n      \"order\": 4,\n      \"canonicalText\": \"雖然，其所以得免於人害者，以其信也，人皆曰獨此一足矣，夔非一足也，一而足也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-19_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-19\",\n      \"order\": 5,\n      \"canonicalText\": \"」哀公曰：「審而是固足矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-19_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-19\",\n      \"order\": 6,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-20_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-20\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-20_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-20\",\n      \"order\": 2,\n      \"canonicalText\": \"哀公問於孔子曰：「吾聞夔一足，信乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-20_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-20\",\n      \"order\": 3,\n      \"canonicalText\": \"」曰：「夔，人也，何故一足？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-20_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-20\",\n      \"order\": 4,\n      \"canonicalText\": \"彼其無他異，而獨通於聲，堯曰：『夔一而足矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-20_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-20\",\n      \"order\": 5,\n      \"canonicalText\": \"』使為樂正。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-20_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-20\",\n      \"order\": 6,\n      \"canonicalText\": \"故君子曰：『夔有一足，非一足也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-20_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-20\",\n      \"order\": 7,\n      \"canonicalText\": \"』」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-21_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-21\",\n      \"order\": 1,\n      \"canonicalText\": \"說三\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-22_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-22\",\n      \"order\": 1,\n      \"canonicalText\": \"文王伐崇，至鳳黃虛，襪繫解，因自結，太公望曰：「何為也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-22_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-22\",\n      \"order\": 2,\n      \"canonicalText\": \"」王曰：「君與處皆其師，中皆其友，下盡其使也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-22_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-22\",\n      \"order\": 3,\n      \"canonicalText\": \"今皆先君之臣，故無可使也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-22_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-22\",\n      \"order\": 4,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-23_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-23\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-23_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-23\",\n      \"order\": 2,\n      \"canonicalText\": \"晉文公與楚戰，至黃鳳之陵，履係解，因自結之，左右曰：「不可以使人乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-23_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-23\",\n      \"order\": 3,\n      \"canonicalText\": \"」公曰：「吾聞上君所與居，皆其所畏也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-23_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-23\",\n      \"order\": 4,\n      \"canonicalText\": \"中君之所與居，皆其所愛也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-23_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-23\",\n      \"order\": 5,\n      \"canonicalText\": \"下君之所與居，皆其所侮也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-23_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-23\",\n      \"order\": 6,\n      \"canonicalText\": \"寡人雖不肖，先君之人皆在，是以難之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-23_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-23\",\n      \"order\": 7,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-24_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-24\",\n      \"order\": 1,\n      \"canonicalText\": \"季孫好士，終身莊，居處衣服，常如朝廷，而季孫適懈，有過失，而不能長為也，故客以為厭易己，相與怨之，遂殺季孫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-24_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-24\",\n      \"order\": 2,\n      \"canonicalText\": \"故君子去泰去甚。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-25_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-25\",\n      \"order\": 1,\n      \"canonicalText\": \"南宮敬子問顏涿聚曰：「季孫養孔子之徒，所朝服與坐者以十數而遇賊，何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-25_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-25\",\n      \"order\": 2,\n      \"canonicalText\": \"」曰：「昔周成王近優侏儒以逞其意，而與君子斷事，是能成其欲於天下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-25_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-25\",\n      \"order\": 3,\n      \"canonicalText\": \"今季孫養孔子之徒，所朝服而與坐者以十數，而與優侏儒斷事，是以遇賊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-25_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-25\",\n      \"order\": 4,\n      \"canonicalText\": \"故曰：不在所與居，在所與謀也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-25_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-25\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-26_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-26\",\n      \"order\": 1,\n      \"canonicalText\": \"孔子御坐於魯哀公，哀公賜之桃與黍，哀公：「請用。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-26_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-26\",\n      \"order\": 2,\n      \"canonicalText\": \"」仲尼先飯黍而後啗桃，左右皆揜口而笑，哀公曰：「黍者，非飯之也，以雪桃也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-26_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-26\",\n      \"order\": 3,\n      \"canonicalText\": \"」仲尼對曰：「丘知之矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-26_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-26\",\n      \"order\": 4,\n      \"canonicalText\": \"夫黍者五穀之長也，祭先王為上盛。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-26_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-26\",\n      \"order\": 5,\n      \"canonicalText\": \"果蓏有六，而桃為下，祭先王不得入廟。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-26_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-26\",\n      \"order\": 6,\n      \"canonicalText\": \"丘之聞也，君子以賤雪貴，不聞以貴雪賤。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-26_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-26\",\n      \"order\": 7,\n      \"canonicalText\": \"今以五穀之長雪果蓏之下，是從上雪下也，丘以為妨義，故不敢以先於宗廟之盛也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-26_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-26\",\n      \"order\": 8,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-27_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-27\",\n      \"order\": 1,\n      \"canonicalText\": \"趙簡子謂左右曰：「車席泰美。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-27_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-27\",\n      \"order\": 2,\n      \"canonicalText\": \"夫冠雖賤，頭必戴之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-27_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-27\",\n      \"order\": 3,\n      \"canonicalText\": \"屨雖貴，足必履之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-27_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-27\",\n      \"order\": 4,\n      \"canonicalText\": \"今車席如此，大美，吾將何屩以履之？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-27_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-27\",\n      \"order\": 5,\n      \"canonicalText\": \"夫美下而耗上，妨義之本也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-27_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-27\",\n      \"order\": 6,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-28_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-28\",\n      \"order\": 1,\n      \"canonicalText\": \"費仲說紂曰：「西伯昌賢，百姓悅之，諸侯附焉，不可不誅，不誅必為殷患。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-28_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-28\",\n      \"order\": 2,\n      \"canonicalText\": \"」紂曰：「子言，義主，何可誅？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-28_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-28\",\n      \"order\": 3,\n      \"canonicalText\": \"」費仲曰：「冠雖穿弊，必戴於頭；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-28_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-28\",\n      \"order\": 4,\n      \"canonicalText\": \"履雖五采，必踐之於地。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-28_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-28\",\n      \"order\": 5,\n      \"canonicalText\": \"今西伯昌，人臣也，修義而人向之，卒為天下患，其必昌乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-28_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-28\",\n      \"order\": 6,\n      \"canonicalText\": \"人人不以其賢為其主，非可不誅也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-28_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-28\",\n      \"order\": 7,\n      \"canonicalText\": \"且主而誅臣，焉有過？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-28_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-28\",\n      \"order\": 8,\n      \"canonicalText\": \"」紂曰：「夫仁義者，上所以勸下也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-28_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-28\",\n      \"order\": 9,\n      \"canonicalText\": \"今昌好仁義，誅之不可。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-28_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-28\",\n      \"order\": 10,\n      \"canonicalText\": \"」三說不用，故亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-29_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-29\",\n      \"order\": 1,\n      \"canonicalText\": \"齊宣王問匡倩曰：「儒者博乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-29_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-29\",\n      \"order\": 2,\n      \"canonicalText\": \"」曰：「不也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-29_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-29\",\n      \"order\": 3,\n      \"canonicalText\": \"」王曰：「何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-29_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-29\",\n      \"order\": 4,\n      \"canonicalText\": \"」匡倩對曰：「博者貴梟，勝者必殺梟，殺梟者，是殺所貴也，儒者以為害義，故不博也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-29_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-29\",\n      \"order\": 5,\n      \"canonicalText\": \"」又問曰：「儒者弋乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-29_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-29\",\n      \"order\": 6,\n      \"canonicalText\": \"」曰：「不也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-29_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-29\",\n      \"order\": 7,\n      \"canonicalText\": \"弋者從下害於上者也，是從下傷君也，儒者以為害義，故不弋。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-29_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-29\",\n      \"order\": 8,\n      \"canonicalText\": \"」又問儒者鼓瑟乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-29_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-29\",\n      \"order\": 9,\n      \"canonicalText\": \"曰：「不也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-29_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-29\",\n      \"order\": 10,\n      \"canonicalText\": \"夫瑟以小絃為大聲，以大絃為小聲，是大小易序，貴賤易位，儒者以為害義，故不鼓也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-29_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-29\",\n      \"order\": 11,\n      \"canonicalText\": \"」宣王曰：「善。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-29_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-29\",\n      \"order\": 12,\n      \"canonicalText\": \"」仲尼曰：「與其使民諂下也，寧使民諂上。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-29_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-29\",\n      \"order\": 13,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-30_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-30\",\n      \"order\": 1,\n      \"canonicalText\": \"說四\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-31_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-31\",\n      \"order\": 1,\n      \"canonicalText\": \"鉅者，齊之居士。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-31_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-31\",\n      \"order\": 2,\n      \"canonicalText\": \"孱者，魏之居士。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-31_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-31\",\n      \"order\": 3,\n      \"canonicalText\": \"齊、魏之君不明，不能親照境內，而聽左右之言，故二子費金璧而求入仕也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-32_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-32\",\n      \"order\": 1,\n      \"canonicalText\": \"西門豹為鄴令，清剋潔愨，秋毫之端無私利也，而甚簡左右，左右因相與比周而惡之，居期年，上計，君收其璽，豹自請曰：「臣昔者不知所以治鄴，今臣得矣，願請璽復以治鄴，不當，請伏斧鑕之罪。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-32_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-32\",\n      \"order\": 2,\n      \"canonicalText\": \"」文侯不忍而復與之，豹因重斂百姓，急事左右，期年，上計，文侯迎而拜之，豹對曰：「往年臣為君治鄴，而君奪臣璽，今臣為左右治鄴，而君拜臣，臣不能治矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-32_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-32\",\n      \"order\": 3,\n      \"canonicalText\": \"」遂納璽而去，文侯不受，曰：「寡人曩不知子，今知矣，願子勉為寡人治之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-32_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-32\",\n      \"order\": 4,\n      \"canonicalText\": \"」遂不受。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-33_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-33\",\n      \"order\": 1,\n      \"canonicalText\": \"齊有狗盜之子與刖危子戲而相誇，盜子曰：「吾父之裘獨有尾。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-33_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-33\",\n      \"order\": 2,\n      \"canonicalText\": \"」危子曰：「吾父獨冬不失褲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-33_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-33\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-34_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-34\",\n      \"order\": 1,\n      \"canonicalText\": \"子綽曰：「人莫能左畫方而右畫圓也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-34_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-34\",\n      \"order\": 2,\n      \"canonicalText\": \"以肉去蟻蟻愈多，以魚驅蠅蠅愈至。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-34_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-34\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-35_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-35\",\n      \"order\": 1,\n      \"canonicalText\": \"桓公謂管仲曰：「官少而索者眾，寡人憂之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-35_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-35\",\n      \"order\": 2,\n      \"canonicalText\": \"」管仲曰：「君無聽左右之謂請，因能而受祿，錄功而與官，則莫敢索官，君何患焉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-35_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-35\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-36_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-36\",\n      \"order\": 1,\n      \"canonicalText\": \"韓宣子曰：「吾馬菽粟多矣，甚臞，何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-36_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-36\",\n      \"order\": 2,\n      \"canonicalText\": \"寡人患之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-36_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-36\",\n      \"order\": 3,\n      \"canonicalText\": \"」周市對曰：「使騶盡粟以食，雖無肥，不可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-36_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-36\",\n      \"order\": 4,\n      \"canonicalText\": \"名為多與之，其實少，雖無臞，亦不可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-36_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-36\",\n      \"order\": 5,\n      \"canonicalText\": \"主不審其情實，坐而患之，馬猶不肥也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-36_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-36\",\n      \"order\": 6,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-37_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-37\",\n      \"order\": 1,\n      \"canonicalText\": \"桓公問置吏於管仲，管仲曰：「辯察於辭，清潔於貨，習人情，夷吾不如弦商，請立以為大理。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-37_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-37\",\n      \"order\": 2,\n      \"canonicalText\": \"登降肅讓，以明禮待賓，臣不如隰朋，請立以為大行。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-37_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-37\",\n      \"order\": 3,\n      \"canonicalText\": \"墾草仞邑，闢地生粟，臣不如甯武，請以為大田。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-37_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-37\",\n      \"order\": 4,\n      \"canonicalText\": \"三軍既成陳，使士視死如歸，臣不如公子成父，請以為大司馬。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-37_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-37\",\n      \"order\": 5,\n      \"canonicalText\": \"犯顏極諫，臣不如東郭牙，請立以為諫臣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-37_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-37\",\n      \"order\": 6,\n      \"canonicalText\": \"治齊此五子足矣，將欲霸王，夷吾在此。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-37_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-37\",\n      \"order\": 7,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-38_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-38\",\n      \"order\": 1,\n      \"canonicalText\": \"說五\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-39_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-39\",\n      \"order\": 1,\n      \"canonicalText\": \"孟獻伯相魯，堂下生藿藜，門外長荊棘，食不二味，坐不重席，晉無衣帛之妾，居不粟馬，出不從車，叔向聞之，以告苗賁皇，賁皇非之曰：「是出主之爵祿以附下也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-39_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-39\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-40\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-40\",\n      \"order\": 2,\n      \"canonicalText\": \"孟獻伯拜上卿，叔嚮往賀，門有御，馬不食禾，向曰：「子無二馬二輿何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-40\",\n      \"order\": 3,\n      \"canonicalText\": \"」獻伯曰：「吾觀國人尚有飢色，是以不秣馬。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-40\",\n      \"order\": 4,\n      \"canonicalText\": \"班白者多以徒行，故不二輿。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-40\",\n      \"order\": 5,\n      \"canonicalText\": \"」向曰：「吾始賀子之拜卿，今賀子之儉也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-40\",\n      \"order\": 6,\n      \"canonicalText\": \"」向出，語苗賁皇曰：「助吾賀獻伯之儉也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-40\",\n      \"order\": 7,\n      \"canonicalText\": \"」苗子曰：「何賀焉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-40\",\n      \"order\": 8,\n      \"canonicalText\": \"夫爵祿旂章，所以異功伐別賢不肖也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-40\",\n      \"order\": 9,\n      \"canonicalText\": \"故晉國之法，上大夫二輿二乘，中大夫二輿一乘，下大夫專乘，此明等級也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-40\",\n      \"order\": 10,\n      \"canonicalText\": \"且夫卿必有軍事，是故循車馬，比卒乘，以備戎事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-40\",\n      \"order\": 11,\n      \"canonicalText\": \"有難則以備不虞，平夷則以給朝事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-40\",\n      \"order\": 12,\n      \"canonicalText\": \"今亂晉國之政，乏不虞之備，以成節，以絜私名，獻伯之儉也可與？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-40\",\n      \"order\": 13,\n      \"canonicalText\": \"又何賀！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-40_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-40\",\n      \"order\": 14,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-41_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-41\",\n      \"order\": 1,\n      \"canonicalText\": \"管仲相齊，曰：「臣貴矣，然而臣貧。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-41_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-41\",\n      \"order\": 2,\n      \"canonicalText\": \"」桓公曰：「使子有三歸之家。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-41_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-41\",\n      \"order\": 3,\n      \"canonicalText\": \"」曰：「臣富矣，然而臣卑。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-41_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-41\",\n      \"order\": 4,\n      \"canonicalText\": \"」桓公使立於高、國之上。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-41_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-41\",\n      \"order\": 5,\n      \"canonicalText\": \"曰：「臣尊矣，然而臣疏。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-41_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-41\",\n      \"order\": 6,\n      \"canonicalText\": \"」乃立為仲父。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-41_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-41\",\n      \"order\": 7,\n      \"canonicalText\": \"孔子聞而非之曰：「泰侈偪上。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-41_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-41\",\n      \"order\": 8,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-42_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-42\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-42_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-42\",\n      \"order\": 2,\n      \"canonicalText\": \"管仲父，出、朱蓋青衣，置鼓而歸，庭有陳鼎，家有三歸，孔子曰：「良大夫也，其侈偪上。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-42_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-42\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-43_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-43\",\n      \"order\": 1,\n      \"canonicalText\": \"孫叔敖相楚，棧車牝馬，糲餅菜羹，枯魚之膳，冬羔裘，夏葛衣，面有飢色，則良大夫也，其儉偪下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-44_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-44\",\n      \"order\": 1,\n      \"canonicalText\": \"陽虎去齊走趙，簡主問曰：「吾聞子善樹人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-44_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-44\",\n      \"order\": 2,\n      \"canonicalText\": \"」虎曰：「臣居魯，樹三人，皆為令尹，及虎抵罪於魯，皆搜索於虎也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-44_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-44\",\n      \"order\": 3,\n      \"canonicalText\": \"臣居齊，薦三人，一人得近王，一人為縣令，一人為候吏，及臣得罪，近王者不見臣，縣令者迎臣執縛，候吏者追臣至境上，不及而止。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-44_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-44\",\n      \"order\": 4,\n      \"canonicalText\": \"虎不善樹人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-44_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-44\",\n      \"order\": 5,\n      \"canonicalText\": \"」主俛而笑曰：「夫樹橘柚者，食之則甘，嗅之則香；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-44_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-44\",\n      \"order\": 6,\n      \"canonicalText\": \"樹枳棘者，成而刺人；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-44_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-44\",\n      \"order\": 7,\n      \"canonicalText\": \"故君子慎所樹。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-44_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-44\",\n      \"order\": 8,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-45_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-45\",\n      \"order\": 1,\n      \"canonicalText\": \"中牟無令，晉平公問趙武曰：「中牟，三國之股肱，邯鄲之肩髀，寡人慾得其良令也，誰使而可？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-45_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-45\",\n      \"order\": 2,\n      \"canonicalText\": \"」武曰：「邢伯子可。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-45_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-45\",\n      \"order\": 3,\n      \"canonicalText\": \"」公曰：「非子之讎也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-45_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-45\",\n      \"order\": 4,\n      \"canonicalText\": \"」曰：「私讎不入公門。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-45_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-45\",\n      \"order\": 5,\n      \"canonicalText\": \"」公又問曰：「中府之令誰使而可？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-45_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-45\",\n      \"order\": 6,\n      \"canonicalText\": \"」曰：「臣子可。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-45_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-45\",\n      \"order\": 7,\n      \"canonicalText\": \"」故曰：「外舉不避讎，內舉不避子。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-45_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-45\",\n      \"order\": 8,\n      \"canonicalText\": \"」趙武所薦四十六人，及武死，各就賓位，其無私德若此也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-46_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-46\",\n      \"order\": 1,\n      \"canonicalText\": \"平公問叔向曰：「群臣孰賢？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-46_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-46\",\n      \"order\": 2,\n      \"canonicalText\": \"」曰：「趙武。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-46_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-46\",\n      \"order\": 3,\n      \"canonicalText\": \"」公曰：「子黨於師人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-46_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-46\",\n      \"order\": 4,\n      \"canonicalText\": \"」曰：「武立如不勝衣，言如不出口，然所舉士也數十人，皆得其意，而公家甚賴之，及武子之生也不利於家，死不託於孤，臣敢以為賢也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-46_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-46\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-47_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-47\",\n      \"order\": 1,\n      \"canonicalText\": \"解狐薦其讎於簡主以為相，其讎以為且幸釋己也，乃因往拜謝，狐乃引弓送而射之，曰：「夫薦汝公也，以汝能當之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-47_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-47\",\n      \"order\": 2,\n      \"canonicalText\": \"夫讎汝，吾私怨也，不以私怨汝之故擁汝於吾君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-47_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-47\",\n      \"order\": 3,\n      \"canonicalText\": \"故私怨不入公門。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-47_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-47\",\n      \"order\": 4,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-48_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-48\",\n      \"order\": 1,\n      \"canonicalText\": \"一曰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-48_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-48\",\n      \"order\": 2,\n      \"canonicalText\": \"解狐舉邢伯柳為上黨守，柳往謝之曰：「子釋罪，敢不再拜。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-48_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-48\",\n      \"order\": 3,\n      \"canonicalText\": \"」曰：「舉子公也，怨子私也，子往矣，怨子如初也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-48_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-48\",\n      \"order\": 4,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-49_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-49\",\n      \"order\": 1,\n      \"canonicalText\": \"鄭縣人賣豚，人問其價，曰：「道日暮安暇語汝。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-49_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-49\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-50_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-50\",\n      \"order\": 1,\n      \"canonicalText\": \"說六\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-51_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-51\",\n      \"order\": 1,\n      \"canonicalText\": \"範文子喜直言，武子擊之以杖：「夫直議者不為人所容，無所容則危身，非徒危身，又將危父。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-51_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-51\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-52_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-52\",\n      \"order\": 1,\n      \"canonicalText\": \"子產者，子國之子也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-52_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-52\",\n      \"order\": 2,\n      \"canonicalText\": \"子產忠於鄭君，子國譙怒之曰：「夫介異於人臣，而獨忠於主，主賢明，能聽汝，不明，將不汝聽，聽與不聽，未可必知，而汝已離於群臣，離於群臣則必危汝身矣，非徒危己也，又且危父矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-52_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-52\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-53_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-53\",\n      \"order\": 1,\n      \"canonicalText\": \"梁車新為鄴令，其姊往看之，暮而後門閉，因踰郭而入，車遂刖其足，趙成侯以為不慈，奪之璽而免之令。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-54_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-54\",\n      \"order\": 1,\n      \"canonicalText\": \"管仲束縛，自魯之齊，道而飢渴，過綺烏封人而乞食，烏封人跪而食之，甚敬，封人因竊謂仲曰：「適幸及齊不死而用齊，將何報我？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-54_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-54\",\n      \"order\": 2,\n      \"canonicalText\": \"」曰：「如子之言，我且賢之用，能之使，勞之論，我何以報子？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-33_p-54_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-33\",\n      \"passageId\": \"han-fei-zi_ch-33_p-54\",\n      \"order\": 3,\n      \"canonicalText\": \"」封人怨之。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
